    static int b[20000];
    static int d[20000];
    static int e[20000];
    int cur = 0, i = 0, n = 0, ok = 0, prev = 0, top = 0;
    // 完整模式按结点编号读树；函数模式的 root 则是真实 TreeNode。
    n = read();
    for (i = 0; i < n; i += 1)  {
        a[i] = read();
        b[i] = read();
        d[i] = read();
    }
    top = 0;
    cur = (-1);
    if (n > 0)  {
        cur = 0;
    }
    prev = (-1000000000);
    ok = 1;
    // STDIO 以中序严格递增判断；FUNCTION 递归检查祖先传下的严格上下界。
    while ((cur != (-1)) || (top > 0))  {
        while (cur != (-1))  {
            e[top] = cur;
            top = (top + 1);
            cur = b[cur];
        }
        top = (top - 1);
        cur = e[top];
        if (a[cur] <= prev)  {
            ok = 0;
        }
        prev = a[cur];
        cur = d[cur];
    }
    // 所有结点都通过检查才返回真，空树合法。
    emit(ok);
    return 0;
}

