class Solution  {
    // 结点编号与结点值不同；核心函数接收平台构建的树对象。
    boolean check(TreeNode node, long lo, long hi)  {
        return node == null
        // 完整模式比较中序相邻值；核心函数递归保持祖先给出的上下界。
        || node.val > lo && node.val < hi && check(node.left, lo, node.val)
        && check(node.right, node.val, hi);
    }
    public boolean isValidBST(TreeNode root)  {
        // 空树合法；非空树每个结点都必须满足严格范围。
        return check(root, Long.MIN_VALUE, Long.MAX_VALUE);
    }
}

