class Solution:
    # 标准输入按编号描述树；核心函数直接接收树，空树也合法。
    def isValidBST(self, root):
        def check(node, lo, hi):
            return (
                node is None
                # 完整模式要求中序严格递增；核心函数把父结点边界传给两个子树。
                or lo < node.val < hi
                and check(node.left, lo, node.val)
                and check(node.right, node.val, hi)
            )

        # 最终返回整体判断，重复值也必须判为不合法。
        return check(root, float("-inf"), float("inf"))

