impl Solution  {
    // 标准输入使用结点编号；核心函数的 Option 表示树结点可能为空。
    pub fn is_valid_bst(root: Option<Rc<RefCell<TreeNode>>>) -> bool  {
        fn check(root: &Option<Rc<RefCell<TreeNode>>>, lo: i64, hi: i64) -> bool  {
            match root  {
                None => true,
                Some(node) =>  {
                    let node = node.borrow();
                    let v = node.val as i64;
                    // 完整模式比较中序相邻值；核心函数保留严格上下界并递归。
                    v > lo && v < hi && check(&node.left, lo, v) && check(&node.right, v, hi)
                }
            }
        }
        // 所有结点通过检查才为真，空 Option 合法。
        check(&root, i64::MIN, i64::MAX)
    }
}
